 platforms.length > 0 && platforms.every(p=>['facebook','instagram'].includes(p)) &&
 typeof body.copy === 'string' && body.copy.trim().length > 0 && body.copy.length <= 2200 &&
 urls.length > 0 && urls.length <= 10 && urls.every(url=>typeof url==='string' && /^https:\/\/[^\s]+$/.test(url));
